docutils.utils.__init__.decode_path:
def decode_path(path: str | bytes | None) -> str:
    """
    Ensure `path` is Unicode. Return `str` instance.

    Decode file/path string in a failsafe manner if not already done.

    Deprecated. Will be removed in Docutils 1.0.
    """
    if isinstance(path, str):
        return path
    if path is None:
        return ''
    try:
        path = path.decode(sys.getfilesystemencoding(), 'strict')
    except AttributeError:
        raise ValueError(f'`path` value must be a String or ``None``, not {path!r}')
    except UnicodeDecodeError:
        try:
            path = path.decode('utf-8', 'strict')
        except UnicodeDecodeError:
            path = path.decode('ascii', 'replace')
    return path

