def get_writer_class(writer_name: str) -> type[Writer]:
    """Return the Writer class from the `writer_name` module."""
    name = writer_name.lower()
    name = WRITER_ALIASES.get(name, name)
    try:
        module = importlib.import_module('docutils.writers.' + name)
    except ImportError:
        try:
            module = importlib.import_module(name)
        except ImportError as err:
            raise ImportError(f'Writer "{writer_name}" not found. {err}')
    return module.Writer

docutils.frontend.validate_colon_separat:
def validate_colon_separated_string_list(setting: str | list[str], value: str | None = None, option_parser: OptionParser | None = None, config_parser: ConfigParser | None = None, config_section: str | None = None) -> list[str]:
    if value is None:
        value = setting
    if not isinstance(value, list):
        value = value.split(':')
    else:
        last = value.pop()
        value.extend(last.split(':'))
    return value

docutils.writers.odf_odt.__init__.escape:
def escape_cdata(text):
    text = text.replace('&', '&amp;')
    text = text.replace('<', '&lt;')
    text = text.replace('>', '&gt;')
    ascii_ = ''
    for char in text:
        if ord(char) >= ord('\x7f'):
            ascii_ += '&#x%X;' % (ord(char), )
        else:
            ascii_ += char
    return ascii_

