def adapt_path(path: str, source='', root_prefix='') -> str:
    if (root_prefix and path.startswith('/')):
        base = Path(root_prefix)
        path = path[1:]
    else:
        base = Path(source).parent
    return utils.relative_path(None, base / path)

docutils.utils.math.latex2mathml.align_a:
def align_attributes(rows):
    atts = {'class': 'ams-align', 'displaystyle': True}
    tabs = max((row.count('&') - row.count('\\&') for row in rows))
    if tabs:
        aligns = ['right', 'left'] * tabs
        spacing = ['0', '2em'] * tabs
        atts['columnalign'] = ' '.join(aligns[:tabs + 1])
        atts['columnspacing'] = ' '.join(spacing[:tabs])
    return atts

