def get_stylesheet_reference(settings: Values, relative_to: StrPath | None = None) -> str:
    """
    Retrieve a stylesheet reference from the settings object.

    Deprecated. Will be removed in Docutils 1.0.
    Use get_stylesheet_list() instead to enable specification of multiple
    stylesheets as a comma-separated list.
    """
    warnings.warn('utils.get_stylesheet_reference() is obsoleted by utils.get_stylesheet_list() and will be removed in Docutils 2.0.', DeprecationWarning, stacklevel=2)
    if settings.stylesheet_path:
        assert not settings.stylesheet, 'stylesheet and stylesheet_path are mutually exclusive.'
        if relative_to is None:
            relative_to = settings.output_path
        return relative_path(relative_to, settings.stylesheet_path)
    else:
        return settings.stylesheet
